struct Point { float x, y; };
struct Matrix { float m11, m12, m21, m22, dx, dy; };

Matrix identity() { return { 0, 0, 0, 0, 0, 0 }; }
Matrix translation(float x, float y) { return identity(); }
Matrix scale(float sx, float sy, Point centre) { return identity(); }
Matrix rotation(float degrees, Point centre) { return identity(); }
Matrix multiply(const Matrix& a, const Matrix& b) { return a; }
Point apply(const Matrix& m, Point p) { return p; }
bool invert(const Matrix& m, Matrix& out) { return false; }
Matrix zoomAt(const Matrix& view, float factor, Point screenPoint) { return view; }

solution.solution.cpp:
#include <cmath>

struct Point { float x, y; };
struct Matrix { float m11, m12, m21, m22, dx, dy; };

Matrix identity() { return { 1, 0, 0, 1, 0, 0 }; }
Matrix translation(float x, float y) { return { 1, 0, 0, 1, x, y }; }

Matrix multiply(const Matrix& a, const Matrix& b)
{
    return { a.m11 * b.m11 + a.m12 * b.m21, a.m11 * b.m12 + a.m12 * b.m22,
             a.m21 * b.m11 + a.m22 * b.m21, a.m21 * b.m12 + a.m22 * b.m22,
             a.dx * b.m11 + a.dy * b.m21 + b.dx, a.dx * b.m12 + a.dy * b.m22 + b.dy };
}

Matrix scale(float sx, float sy, Point c)
{
    return multiply(multiply(translation(-c.x, -c.y), Matrix{ sx, 0, 0, sy, 0, 0 }), translation(c.x, c.y));
}

Matrix rotation(float degrees, Point c)
{
    const float r{ degrees * 3.14159265358979f / 180.0f };
    const float co{ std::cos(r) }, si{ std::sin(r) };
    return multiply(multiply(translation(-c.x, -c.y), Matrix{ co, si, -si, co, 0, 0 }), translation(c.x, c.y));
}

Point apply(const Matrix& m, Point p)
{
    return { p.x * m.m11 + p.y * m.m21 + m.dx, p.x * m.m12 + p.y * m.m22 + m.dy };
}

bool invert(const Matrix& m, Matrix& out)
{
    const float det{ m.m11 * m.m22 - m.m12 * m.m21 };
    if (std::fabs(det) < 1e-12f) return false;
    const float i11{ m.m22 / det }, i12{ -m.m12 / det }, i21{ -m.m21 / det }, i22{ m.m11 / det };
    out = { i11, i12, i21, i22, -(m.dx * i11 + m.dy * i21), -(m.dx * i12 + m.dy * i22) };
    return true;
}

Matrix zoomAt(const Matrix& view, float factor, Point screenPoint)
{
    return multiply(view, scale(factor, factor, screenPoint));
}

unitTests:
bool nearP(Point p, float x, float y) { return std::fabs(p.x - x) < 1e-3f && std::fabs(p.y - y) < 1e-3f; }
TEST("basic transforms") {
    CHECK(nearP(apply(translation(10, 5), { 1, 2 }), 11, 7)); CHECK(nearP(apply(scale(2, 3, { 0, 0 }), { 1, 2 }), 2, 6));
    CHECK(nearP(apply(scale(2, 2, { 10, 10 }), { 15, 10 }), 20, 10)); CHECK(nearP(apply(rotation(90, { 0, 0 }), { 1, 0 }), 0, 1));
    CHECK(nearP(apply(rotation(90, { 5, 5 }), { 6, 5 }), 5, 6));
}
TEST("order matters") {
    const Matrix spinThenMove = multiply(rotation(90, { 0, 0 }), translation(100, 0));
    const Matrix moveThenSpin = multiply(translation(100, 0), rotation(90, { 0, 0 }));
    CHECK(nearP(apply(spinThenMove, { 10, 0 }), 100, 10)); CHECK(nearP(apply(moveThenSpin, { 10, 0 }), 0, 110));
}
TEST("inverse") {
    const Matrix m = multiply(multiply(scale(2, 4, { 3, 3 }), rotation(30, { 0, 0 })), translation(-7, 12));
    Matrix inv{}; CHECK(invert(m, inv)); CHECK(nearP(apply(inv, apply(m, { 4.5f, -2 })), 4.5f, -2));
    Matrix none{}; CHECK(!invert({ 1, 2, 2, 4, 0, 0 }, none));
}
TEST("zooming around the mouse") {
    const Matrix view = multiply(scale(1.5f, 1.5f, { 0, 0 }), translation(40, 30));
    Matrix inv{}; invert(view, inv); const Point under = apply(inv, { 300, 200 });
    const Matrix zoomed = zoomAt(view, 2, { 300, 200 });
    CHECK(nearP(apply(zoomed, under), 300, 200)); CHECK(nearP(apply(zoomed, { 0, 0 }), -220, -140));
}

